Definition rf1_at (L S Zr : list (word * word)) (mo : Model)
    (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32) (m : mem)
    (lo c CA P R sb ARI rbeg FAB TH TSD CTX nf mfa au mu : Z) (fl : list Z) (msF' : machine_state) (mo' : Model) : Prop :=
  exists (t0 t1 t2 a6 a7 s2' x5 x6 x7 x8 x9 s10' s11' t3 t4 t5 t6 q0 q1 q2 q3 : word) (j8 j24 : list byte) m',
  let n := rf_n c in
     lzok bsegs L S Zr (mkCfg msF' mo')
  /\ restrict L S msF'
     = MS (mkR (wz 0x54fa4) (Z_to_bv 64 (bv_unsigned sp + -160)) gp tp t0 t1 t2 (wz R) (wz AINST) (wz (R + 8)) (wz (CA + 2560)) (wz c) (wz (P + 16)) (wz n) (wz nf) a6 a7
               s2' (wz (2^61)) (wz FAB) x5 x6 x7 x8 x9 s10' s11' t3 t4 t5 t6)
          F (Z_to_bv 64 (if nf <? n then 0x55304 else 0x551bc)) fc None m' (seg_rom bsegs)
  /\ same_but_materialized mo mo'
  /\ munch ((lo, bv_unsigned sp) :: (R, R + 8) :: icW CA) m m' /\ wmono bsegs m m' /\ mem_inv bsegs m'
  /\ RENV tp TSD CTX TH sb ARI m'
  /\ stk bsegs m' lo (bv_unsigned sp + -160)
  /\ rw_cells bsegs m' (bv_unsigned sp + -160)
       [CB 24 j24; C8 s11; C8 s10; C8 s9; C8 s8; C8 s7; C8 s6; C8 s5; C8 s4; C8 s3; C8 s2; C8 (wz n); C8 (wz P); C8 (wz 0x54fa4)]
  /\ rw_cells bsegs m' (bv_unsigned sp + -32) [CB 8 j8; C8 s1; C8 s0; C8 ra]
  /\ rw_cells bsegs m' P [C4 (wz 0)] /\ stk bsegs m' (P + 16) (P + 80)
  /\ (forall c', 1 <= c' <= 31 -> rw_cells bsegs m' (CA + 80 * c' + 4) [C4 (wz (max_count c'))] /\ rw_cells bsegs m' (CA + 80 * c' + 8) [C8 (wz (class_size c'))])
  /\ rw_cells bsegs m' (TH + 2768) [C8 q0; C8 q1; C8 q2; C8 q3] /\ stk bsegs m' (TH + 2800) (TH + 3168)
